package dev.tiertagger.client;
import dev.tiertagger.core.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import com.sun.net.httpserver.HttpServer;
import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;

final class RestrictionScreenTest {
 static void check(boolean value,String why){if(!value)throw new AssertionError(why);}
 static void run(ClientGameTestContext context){
  final UUID[] uuid={null};final String[] name={null};context.runOnClient(client->{uuid[0]=client.player.getUUID();name[0]=client.player.getName().getString();});
  MinecraftIdentityResolver previousResolver=RestrictionChecks.identities;RestrictionClient previousApi=RestrictionChecks.api;
  HttpServer server;AtomicInteger calls=new AtomicInteger();AtomicBoolean mismatch=new AtomicBoolean();
  try{server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{String path=e.getRequestURI().getPath();String body;int code=200;
   if(path.startsWith("/identity/")){String id=(mismatch.get()?UUID.randomUUID():uuid[0]).toString().replace("-","");body="{\"id\":\""+id+"\",\"name\":\""+name[0]+"\"}";}
   else{calls.incrementAndGet();check(path.contains(uuid[0].toString().replace("-","")),"restrictions requested using resolved UUID");body=fixture(uuid[0],name[0]);}
   byte[] bytes=body.getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(code,bytes.length);e.getResponseBody().write(bytes);e.close();});server.start();}catch(Exception e){throw new AssertionError(e);}
  URI base=URI.create("http://127.0.0.1:"+server.getAddress().getPort()+"/");
  try(var identities=new MinecraftIdentityResolver(base.resolve("identity/"));var api=new RestrictionClient(base.resolve("api/"))){
   context.runOnClient(client->{RestrictionChecks.identities=identities;RestrictionChecks.api=api;RestrictionChecks.entries.clear();});
   var messages=new CopyOnWriteArrayList<net.minecraft.network.chat.Component>();context.runOnClient(client->RestrictionChecks.command(name[0],messages::add));context.waitFor(client->messages.stream().anyMatch(c->c.getString().contains("Open full details")));
   context.runOnClient(client->{check(messages.stream().anyMatch(c->c.getString().contains("1 active")),"local command summary");check(messages.stream().anyMatch(c->c.getString().contains("SAMPLE DATA")),"sample is disclosed");check(calls.get()==1,"one UUID request");com.mojang.brigadier.CommandDispatcher<?> dispatcher;try{Class<?> commands;try{commands=Class.forName("net.fabricmc.fabric.api.client.command.v2.ClientCommandManager");}catch(ClassNotFoundException ex){commands=Class.forName("net.fabricmc.fabric.api.client.command.v2.ClientCommands");}dispatcher=(com.mojang.brigadier.CommandDispatcher<?>)commands.getMethod("getActiveDispatcher").invoke(null);}catch(ReflectiveOperationException ex){throw new AssertionError(ex);}check(dispatcher.getRoot().getChild("check")!=null,"check command registered");check(dispatcher.getRoot().getChild("tiertagger").getChild("check")!=null,"namespaced command registered");com.mojang.brigadier.CommandDispatcher rawDispatcher=dispatcher;rawDispatcher.register(com.mojang.brigadier.builder.LiteralArgumentBuilder.literal("check").executes(ctx->42));check(dispatcher.getRoot().getChild("tiertagger").getChild("check").getChild("username").getCommand()!=null,"namespaced check survives competing root check command");});
   context.runOnClient(client->RestrictionChecks.scan());context.waitFor(client->!RestrictionChecks.scanning);
   context.runOnClient(client->{check(RestrictionChecks.completed()>0,"online snapshot completed");check(RestrictionChecks.entries.stream().allMatch(entry->entry.result!=null||entry.complete),"partial failures accounted for");});
   context.runOnClient(client->RestrictionChecks.scanSnapshot(List.of(new RestrictionChecks.Entry(name[0],uuid[0]),new RestrictionChecks.Entry("Unknown",UUID.randomUUID()))));context.waitFor(client->!RestrictionChecks.scanning);
   context.runOnClient(client->{check(RestrictionChecks.entries.getFirst().result!=null,"successful result retained on partial failure");check(RestrictionChecks.entries.getLast().complete&&RestrictionChecks.entries.getLast().result==null,"partial failure visible");});
   context.runOnClient(client->{List<RestrictionChecks.Entry> large=new ArrayList<>();for(int i=0;i<1000;i++)large.add(new RestrictionChecks.Entry(name[0],UUID.randomUUID()));RestrictionChecks.scanSnapshot(large);check(RestrictionChecks.entries.size()==1000,"entire large snapshot retained");check(RestrictionChecks.completed()<=1,"large snapshot scheduled gradually");});context.waitTicks(3);context.runOnClient(client->{check(RestrictionChecks.completed()<20,"cache hits do not recursively burst through snapshot");RestrictionChecks.cancelScan();check(!RestrictionChecks.scanning,"large scan cancels");check(calls.get()==1,"mismatched large snapshot never queries restrictions");});
   context.runOnClient(client->RestrictionChecks.scanSnapshot(List.of(new RestrictionChecks.Entry(name[0],uuid[0]),new RestrictionChecks.Entry("Unknown",UUID.randomUUID()))));context.waitFor(client->!RestrictionChecks.scanning);
   context.setScreen(()->new RestrictionScreen(null,null));context.waitTicks(5);context.takeScreenshot("restriction-online");
   context.runOnClient(client->{var result=RestrictionChecks.entries.getFirst().result;check(result!=null,"fixture restriction result");client.setScreenAndShow(new RestrictionScreen(null,result));});context.waitTicks(5);context.takeScreenshot("restriction-detail");
   context.clickScreenButton("Scroll down");context.waitTicks(5);context.takeScreenshot("restriction-detail-scrolled");
   context.runOnClient(client->{BaseRestrictionScreen screen=(BaseRestrictionScreen)Platform.screen(client);screen.resize(320,180);check(screen.viewTop>=screen.top&&screen.viewBottom<=screen.top+screen.boxHeight,"small viewport contained");check(screen.visibleCount()>0,"small viewport scroll region usable");});context.waitTicks(5);context.takeScreenshot("restriction-small");
   context.runOnClient(client->scale(client,1));context.waitTicks(5);context.takeScreenshot("restriction-scale-one");
   context.runOnClient(client->scale(client,2));context.waitTicks(5);context.takeScreenshot("restriction-scale-two");
   context.clickScreenButton("Support");context.waitTicks(3);context.runOnClient(client->check(Platform.screen(client) instanceof net.minecraft.client.gui.screens.ConfirmLinkScreen,"support opens Minecraft link confirmation"));
   context.runOnClient(client->{RestrictionChecks.scanSnapshot(List.of(new RestrictionChecks.Entry(name[0],uuid[0])));RestrictionChecks.cancelScan();check(!RestrictionChecks.scanning,"scan cancellation");});
   context.runOnClient(client->{RestrictionChecks.cancelScan();RestrictionChecks.disconnect();check(RestrictionChecks.entries.isEmpty(),"disconnect clears visible scan");});
   mismatch.set(true);
   try(var wrongResolver=new MinecraftIdentityResolver(base.resolve("identity/"))){context.runOnClient(client->{RestrictionChecks.identities=wrongResolver;RestrictionChecks.scan();});context.waitFor(client->!RestrictionChecks.scanning);context.runOnClient(client->{check(RestrictionChecks.entries.stream().allMatch(entry->entry.result==null),"premium identity mismatch blocks request");check(calls.get()==1,"mismatched identity never queries restrictions");});}
  }finally{server.stop(0);context.runOnClient(client->{RestrictionChecks.identities=previousResolver;RestrictionChecks.api=previousApi;RestrictionChecks.disconnect();});}
 }
 static void scale(net.minecraft.client.Minecraft client,int scale){client.options.guiScale().set(scale);try{java.lang.reflect.Method resize;try{resize=client.getClass().getMethod("resizeGui");}catch(NoSuchMethodException ex){resize=client.getClass().getMethod("resizeDisplay");}resize.invoke(client);}catch(ReflectiveOperationException ex){throw new AssertionError(ex);}}
 static String fixture(UUID id,String name){return """
 {"data":{"player":{"uuid":"%s","username":"%s","nameUnavailable":false,"profileUrl":"https://restricttiers.raincakecat.com/player/%s"},"counts":{"active":1,"past":1},"active":[{"community":"Fixture community with a deliberately long name","reason":"This is synthetic test data. A long reason checks that the detail wraps inside the panel at different GUI scales and never escapes the scrolling region.","categories":["Fixture"],"durationDays":null,"restrictedAt":null,"expiresAt":null,"archivedAt":null,"verification":"needs_review","sourceUrl":"https://example.org/source"}],"past":[{"community":"Past fixture","reason":"Archived fixture only","categories":[],"durationDays":7,"restrictedAt":"2026-01-01T00:00:00Z","expiresAt":null,"archivedAt":"2026-02-01T00:00:00Z","verification":"no_review_flag","sourceUrl":null}],"pagination":{"page":1,"pageSize":50,"totalPages":1,"nextPage":null,"nextUrl":null},"limits":{"activeMaximum":100,"pastPerPage":50,"maximumPage":10000,"activeTruncated":false,"pastTruncated":false,"hasMorePast":false,"beyondPageLimit":false},"sample":true,"notice":"Synthetic test result"},"meta":{"apiVersion":"1","requestId":"ui-fixture","respondedAt":"2026-11-12T12:00:00Z"}}
 """.formatted(id.toString().replace("-",""),name,id);}
}
